VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,8.75,"Lecture seven. The Paxos protocol. This is how a group of machines agrees on one value, even when some fail."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":18.344,"caps":[[0.5,4.51,"Two-phase commit needs all five to say yes."],[4.76,8.45,"One crash and it is stuck waiting."],[8.7,12.23,"Paxos needs a majority: 3 of 5."],[12.48,16.41,"2 may crash."]],"warp":[[0,0],[0.5,0.6],[4.76,3.4],[8.7,6],[12.48,8.6],[18.344,10]]},{"dur":18.344,"caps":[[0.5,3.71,"A node can play three roles."],[3.96,7.33,"Proposers suggest a value."],[7.58,12.31,"Acceptors decide which one is chosen."],[12.56,16.49,"Learners are only told the result."]],"warp":[[0,0],[0.5,0.6],[3.96,3.1],[7.58,5.2],[12.56,7.6],[18.344,11]]},{"dur":21.757,"caps":[[0.5,5.07,"Each proposal gets a unique number."],[5.32,12.21,"Proposers never share a number."],[12.46,15.59,"A bigger number means newer."],[15.84,20.89,"The newer proposal beats the older."]],"warp":[[0,0],[0.5,0.5],[5.32,2.8],[12.46,5.2],[15.84,7.7],[21.757,11]]},{"dur":18.227,"caps":[[0.5,4.59,"A majority of 5 is 3: a quorum."],[4.84,7.73,"So 2 may crash."],[7.98,13.99,"Two majorities always overlap."],[14.24,17.37,"They share at least one acceptor."]],"warp":[[0,0],[0.5,0.5],[4.84,3.2],[7.98,5.6],[14.24,8.2],[18.227,11.5]]},{"dur":21.711,"caps":[[0.5,3.71,"Phase 1. Acceptor E is down."],[3.96,7.49,"PREPARE 1 goes to all."],[7.74,10.79,"Acceptors answer PROMISE."],[11.04,15.29,"3 promises make a quorum."],[15.54,19.95,"A promise: ignore older proposals."]],"warp":[[0,0],[0.5,0.5],[3.96,2.7],[7.74,4.9],[11.04,7.2],[15.54,9.8],[21.711,13]]},{"dur":21.618,"caps":[[0.5,4.43,"Phase 2: ask them to accept."],[4.68,8.53,"ACCEPT carries number and value."],[8.78,11.83,"Acceptors tell the learners."],[12.08,15.77,"A majority accepted: it is chosen."],[16.02,19.55,"The learners are told: 7."]],"warp":[[0,0],[0.5,0.5],[4.68,2.8],[8.78,5.2],[12.08,7.7],[16.02,10.7],[21.618,13]]},{"dur":26.679,"caps":[[0.5,2.91,"Two proposers can collide."],[3.16,7.49,"P1 asks A, B, C to promise 1."],[7.74,12.47,"P2 asks B to E to promise 2."],[12.72,17.69,"B and C ignore the older number."],[17.94,21.23,"P2 has a majority: 9 is chosen."],[21.48,24.53,"P1 must retry with 3."]],"warp":[[0,0],[0.5,0.5],[3.16,2.9],[7.74,5.1],[12.72,7.3],[17.94,9.7],[21.48,11.9],[26.679,14]]},{"dur":25.008,"caps":[[0.5,4.43,"P1 crashed after A and B accepted 7."],[4.68,10.21,"P2 asks B, C, D to promise 2."],[10.46,15.03,"B reports the 7 it accepted."],[15.28,19.69,"So P2 must send 7, not its own 9."],[19.94,23.55,"7 stays chosen: it is safe."]],"warp":[[0,0],[0.5,0.5],[4.68,3.2],[10.46,5.6],[15.28,8.1],[19.94,10.8],[25.008,13]]},{"dur":23.429,"caps":[[0.5,5.39,"Each log entry is one Paxos round."],[5.64,12.13,"Round 1 chose +50: 100 → 150."],[12.38,17.51,"Round 2 chose −20: 150 → 130."],[17.76,21.85,"Every replica gets the same order."]],"warp":[[0,0],[0.5,0.5],[5.64,3.2],[12.38,7],[17.76,9.4],[23.429,12.5]]},{"dur":14.907,"caps":[],"warp":[[0,0],[0.5,0.9],[6.04,2],[9.9,3.1],[14.907,9]]}]};
